#include <array>
#include <cstddef>

template<std::size_t Capacity>
class RingQueue {
    static_assert(Capacity > 0);
    std::array<int, Capacity> slots_{};
    std::size_t head_ = 0;
    std::size_t count_ = 0;

    std::size_t slot(std::size_t offset) const noexcept {
        const std::size_t until_end = Capacity - head_;
        return offset < until_end ? head_ + offset : offset - until_end;
    }
public:
    std::size_t size() const noexcept { return count_; }

    bool try_push(int value) noexcept {
        if (count_ == Capacity) return false;
        slots_[slot(count_)] = value;
        ++count_;
        return true;
    }

    bool try_front(int& value) const noexcept {
        if (count_ == 0) return false;
        value = slots_[head_];
        return true;
    }

    bool try_pop(int& value) noexcept {
        if (count_ == 0) return false;
        value = slots_[head_];
        head_ = head_ == Capacity - 1 ? 0 : head_ + 1;
        --count_;
        return true;
    }
};

#include <deque>
#include <iostream>

// Test-only observer: compare the entire logical state without changing it.
template<std::size_t Capacity>
bool same_sequence(RingQueue<Capacity> actual, std::deque<int> expected) {
    if (actual.size() != expected.size()) return false;
    while (!expected.empty()) {
        int value = -777;
        if (!actual.try_pop(value) || value != expected.front()) return false;
        expected.pop_front();
    }
    int value = -777;
    return !actual.try_pop(value) && value == -777 && actual.size() == 0;
}

template<std::size_t Capacity>
bool check_all(std::size_t& checked) {
    std::size_t patterns = 1;
    for (int length = 0; length <= 6; ++length) {
        for (std::size_t pattern = 0; pattern < patterns; ++pattern) {
            RingQueue<Capacity> actual;
            std::deque<int> expected;
            if (!same_sequence(actual, expected)) return false;
            std::size_t remaining = pattern;
            for (int step = 0; step < length; ++step) {
                const unsigned op = static_cast<unsigned>(remaining % 4);
                remaining /= 4;
                int actual_value = -777;
                int expected_value = -777;
                bool actual_ok = false;
                bool expected_ok = false;
                if (op < 2) {
                    const int value = op == 0 ? 14 : 8;
                    actual_ok = actual.try_push(value);
                    expected_ok = expected.size() < Capacity;
                    if (expected_ok) expected.push_back(value);
                } else {
                    actual_ok = op == 2 ? actual.try_pop(actual_value)
                                        : actual.try_front(actual_value);
                    expected_ok = !expected.empty();
                    if (expected_ok) {
                        expected_value = expected.front();
                        if (op == 2) expected.pop_front();
                    }
                }
                if (actual_ok != expected_ok || actual_value != expected_value ||
                    !same_sequence(actual, expected)) {
                    std::cout << "mismatch: capacity=" << Capacity
                              << " length=" << length << " pattern=" << pattern
                              << " step=" << step << '\n';
                    return false;
                }
            }
            ++checked;
        }
        patterns *= 4;
    }
    return true;
}

int main() {
    std::size_t checked = 0;
    if (!check_all<1>(checked) || !check_all<3>(checked)) return 1;
    std::cout << "verified " << checked << " operation sequences\n";
}
